-- Daily challenges for 2026-10-19: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-10-19. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('growing-something-green', 'Growing Something Green', 'For anyone who would like a little more life around them, with or without a yard. Each day is one small step in growing plants, from a windowsill herb to a community garden plot, so tending something living becomes a quiet daily pleasure.', 'Wellbeing', 365, array['Self-Care', 'Mindfulness']::text[], 1, '2026-10-19T17:00:00+00:00'::timestamptz),
  ('finding-patience-in-everyday-waiting', 'Finding Patience in Everyday Waiting', 'For anyone who gets wound up in lines, on hold or stuck behind a slow driver. Each day is one small way to turn waiting into a calmer moment, so delays sting a little less and the rest of the day goes more smoothly.', 'Stress', 365, array['Stress', 'Mindfulness', 'Anger']::text[], 1, '2026-10-19T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('growing-something-green', 'finding-patience-in-everyday-waiting');

